<script setup lang="ts">
import { computed, type PropType } from 'vue';
import { useStore } from 'vuex';
import * as jsyaml from 'js-yaml';
import { escape } from 'lodash';
import { useI18n } from '@shell/composables/useI18n';
import RcButton from '@components/RcButton/RcButton.vue';
import Banner from '@components/Banner/Banner.vue';
import { warn } from '../../utils/log';
import { ConfirmationStatus, ConfirmationActionType, Message } from '../../types';
import { ToolName } from '../../components/tools/types';
import Tools from '../tools/index.vue';

const store = useStore();
const { t } = useI18n(store);

const props = defineProps({
  message: {
    type:    Object as PropType<Message>,
    default: () => ({} as Message),
  },
});

const emit = defineEmits(['confirm']);

const hasDeleteActions = computed(() => {
  return props.message.confirmation?.actions?.some((action) => action.type === ConfirmationActionType.Delete);
});

const CONFIRMATION_STATUS: Partial<Record<ConfirmationStatus, { icon: string; label: string }>> = {
  [ConfirmationStatus.Confirmed]: {
    icon:  'icon icon-checkmark',
    label: t('ai.confirmation.confirmed'),
  },
  [ConfirmationStatus.Canceled]: {
    icon:  'icon icon-close',
    label: t('ai.confirmation.canceled'),
  },
};

const confirmationText = computed(() => {
  try {
    let out = '';

    props.message.confirmation?.actions?.forEach((action) => {
      const actionType = action?.type || ConfirmationActionType.Create;

      // Handle custom agent tool actions separately
      if (actionType === ConfirmationActionType.External) {
        if (action.tool?.name && action.tool?.args !== undefined) {
          const toolLabel = t('ai.confirmation.message.operation.external.tool', {}, true);
          const argsLabel = t('ai.confirmation.message.operation.external.args', {}, true);

          out += `${ toolLabel }: <code>${ escape(action.tool.name) }</code><br>`;

          let argsStr: string;

          if (typeof action.tool.args === 'string') {
            argsStr = escape(action.tool.args);
          } else {
            const yamlStr = jsyaml.dump(action.tool.args, { lineWidth: -1 });

            argsStr = escape(yamlStr);
          }

          out += `${ argsLabel }:<br><code class="external-args-code">${ argsStr }</code><br><br>`;
        }

        return;
      }

      // Handle built-in agent resource-based actions (create/update/patch)
      const {
        kind, name, namespace, cluster
      } = action?.resource || {};

      if (kind && name && cluster) {
        switch (actionType) {
        case ConfirmationActionType.Create:
        case ConfirmationActionType.Delete:
          out += `${ t(`ai.confirmation.message.operation.${ actionType }.description`, {
            name,
            kind,
            namespace: namespace?.trim() || null,
            cluster,
            value:     JSON.stringify(action.payload)
          }, true)  }<br>`;
          break;
        case ConfirmationActionType.Update:
        case ConfirmationActionType.Patch:
          const description = action?.payload?.patch?.reduce((acc: string, curr) => {
            const { op, value, path } = curr || {};

            if (op && value && path) {
              return `${ acc + t(`ai.confirmation.message.operation.update.description`, {
                op,
                value:     typeof value === 'string' ? value : JSON.stringify(value),
                path,
                name,
                kind,
                namespace: namespace?.trim() || null,
                cluster
              }, true) }<br>`;
            }

            return acc;
          }, '');

          if (!!description?.trim()) {
            out += `${ description }<br>`;
          }
          break;
        }
      }
    });

    return out;
  } catch (e) {
    warn('Error generating confirmation description:', e);
  }

  return '';
});

const details = computed(() => (props.message.confirmation?.actions || [])
  .map((action) => action.detail?.trim())
  .filter((detail) => !!detail));

const buttonLabels = computed(() => {
  return {
    // The agent does not support multiple actions as of now, so we have only one action in the array.
    confirm: hasDeleteActions.value ? t('ai.confirmation.delete') : t('ai.confirmation.confirm'),
    cancel:  t('ai.confirmation.cancel')
  };
});
</script>

<template>
  <div class="confirmation-action">
    <div
      v-if="confirmationText"
      class="confirmation-message"
    >
      <span
        v-clean-html="confirmationText"
        data-testid="rancher-ai-ui-chat-message-confirmation-message"
      />
    </div>
    <div
      class="confirmation-message"
      data-testid="rancher-ai-ui-chat-message-confirmation-question"
    >
      {{ t('ai.confirmation.message.question') }}
    </div>
    <Banner
      v-for="(detail, i) in details"
      :key="i"
      class="confirmation-detail"
      color="warning"
      :label="detail"
      data-testid="rancher-ai-ui-chat-message-confirmation-detail"
    />
    <div
      v-if="props.message.confirmation?.status === ConfirmationStatus.Pending"
      class="confirmation-buttons"
    >
      <RcButton
        small
        variant="link"
        :aria-label="buttonLabels.cancel"
        data-testid="rancher-ai-ui-chat-message-confirmation-cancel-button"
        @click="emit('confirm', false)"
      >
        <span class="rc-button-label">
          {{ buttonLabels.cancel }}
        </span>
      </RcButton>
      <RcButton
        :class="{ 'delete-action': hasDeleteActions }"
        small
        variant="tertiary"
        :aria-label="buttonLabels.confirm"
        data-testid="rancher-ai-ui-chat-message-confirmation-confirm-button"
        @click="emit('confirm', true)"
      >
        <span class="rc-button-label">
          {{ buttonLabels.confirm }}
        </span>
      </RcButton>
    </div>
    <div
      v-else-if="props.message.confirmation"
      class="confirmation-status"
      :class="`status-${ props.message.confirmation.status }`"
      :data-testid="`rancher-ai-ui-chat-message-confirmation-status-${ props.message.confirmation.status }`"
    >
      <i :class="CONFIRMATION_STATUS[props.message.confirmation.status]?.icon" />
      <p>
        {{ CONFIRMATION_STATUS[props.message.confirmation.status]?.label }}
      </p>
    </div>
    <Tools
      :key="props.message.tools?.length"
      class="mmt-2"
      :message="props.message"
      :include="[
        ToolName.ShowYaml,
        ToolName.ShowYamlDiff,
      ]"
      :show-default-labels="true"
      @action="emit('confirm', $event)"
    />
  </div>
</template>

